"""Page Object (generated by GenNAI): one method per element, fallback locators."""

import time

LOCATE_TIMEOUT_S = 5.0
CANDIDATES = {'e01': [('css', '#susbscribe_email'), ('placeholder', 'Your email address')],
 'e02': [('role:button', 'Test Cases')],
 'e03': [('role:button', 'APIs list for practice')],
 'e04': [('css', '#subscribe')],
 'e05': [('text', 'Home')],
 'e06': [('role:link', '\ue8f8 Products'), ('text', '\ue8f8 Products')],
 'e07': [('text', 'Cart')],
 'e08': [('text', 'Signup / Login')],
 'e09': [('role:link', 'Test Cases')],
 'e10': [('text', 'API Testing')],
 'e11': [('text', 'Video Tutorials')],
 'e12': [('text', 'Contact us')],
 'e13': [('role:link', 'Test Cases')],
 'e14': [('role:link', 'APIs list for practice')],
 'e15': [('role:link', '(5) H&M')],
 'e16': [('role:link', 'Tshirt'), ('text', 'Tshirt')],
 'e17': [('role:link', 'Dress')],
 'e18': [('role:link', 'Outfits'), ('text', 'Outfits')]}


class LocatorNotFound(Exception):
    """None of an element's candidate locators matched exactly one element."""


def locate(page, strategy, value):
    """Playwright locator for one (strategy, value) candidate. Also embedded in generated tests."""
    if strategy == "testid":
        return page.get_by_test_id(value)
    if strategy == "css":
        return page.locator(value)
    if strategy.startswith("role:"):
        return page.get_by_role(strategy[5:], name=value, exact=True)
    if strategy == "label":
        return page.get_by_label(value, exact=True)
    if strategy == "placeholder":
        return page.get_by_placeholder(value, exact=True)
    return page.get_by_text(value, exact=True)


class Page:
    def __init__(self, page):
        self.page = page

    def _find(self, key):
        deadline = time.monotonic() + LOCATE_TIMEOUT_S
        while True:
            for strategy, value in CANDIDATES[key]:
                loc = locate(self.page, strategy, value)
                if loc.count() == 1:
                    return loc
            if time.monotonic() >= deadline:
                raise LocatorNotFound(f"{key}: no unique match among {CANDIDATES[key]!r}")
            self.page.wait_for_timeout(100)

    def e01_input(self):
        return self._find('e01')

